/** Query-level contract for grouping authoritative predicate-plane counts by a computed predicate property. */
public class LmdbPredicatePlaneGroupingTest {

	private static final String EX = "http://example.com/";
	private static final String NAMESPACE_COUNTS = "SELECT ?ns (COUNT(*) AS ?statements) "
			+ "(COUNT(DISTINCT ?p) AS ?predicates) WHERE {\n"
			+ "  ?s ?p ?o .\n"
			+ "  BIND(REPLACE(STR(?p), \"[^/#]+$\", \"\") AS ?ns)\n"
			+ "}\n"
			+ "GROUP BY ?ns\n"
			+ "ORDER BY DESC(?statements) ?ns";
	private static final String MULTI_CHANNEL_COUNTS = "SELECT ?ns (COUNT(*) AS ?star) "
			+ "(COUNT(?s) AS ?subjects) (COUNT(?p) AS ?predicateRows) (COUNT(?o) AS ?objects) "
			+ "(COUNT(DISTINCT ?p) AS ?predicates) WHERE {\n"
			+ "  ?s ?p ?o .\n"
			+ "  BIND(REPLACE(STR(?p), \"[^/#]+$\", \"\") AS ?ns)\n"
			+ "}\n"
			+ "GROUP BY ?ns\n"
			+ "ORDER BY DESC(?star) ?ns";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@AfterEach
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	@Test
	public void namespaceCountsUseOnePredicatePlaneRowPerPredicate() throws InterruptedException {
		LmdbStore store = openRepository();
		assertThat(store.awaitDirectAdjacencyReady(60, TimeUnit.SECONDS)).isTrue();

		try (SailRepositoryConnection connection = repository.getConnection()) {
			List<String> rows = new ArrayList<>();
			for (BindingSet row : QueryResults.asList(connection.prepareTupleQuery(NAMESPACE_COUNTS).evaluate())) {
				rows.add(row.getValue("ns").stringValue() + "="
						+ ((Literal) row.getValue("statements")).longValue() + "="
						+ ((Literal) row.getValue("predicates")).longValue());
			}
			assertThat(rows).containsExactly(EX + "a/=4=2", EX + "b#=2=1", EX + "end/=1=1");
			assertThat(executionPath(connection, NAMESPACE_COUNTS)).isEqualTo("predicatePlaneGroups");
		}
	}

	@Test
	public void multipleBagAndDistinctChannelsShareThePlaneTraversal() throws InterruptedException {
		LmdbStore store = openRepository();
		assertThat(store.awaitDirectAdjacencyReady(60, TimeUnit.SECONDS)).isTrue();
		long planesBefore = LmdbNativePredicatePlaneGroups.PLANES.get();
		long decodesBefore = LmdbNativePredicatePlaneGroups.PREDICATE_DECODES.get();

		try (SailRepositoryConnection connection = repository.getConnection()) {
			List<String> rows = new ArrayList<>();
			for (BindingSet row : QueryResults.asList(connection.prepareTupleQuery(MULTI_CHANNEL_COUNTS).evaluate())) {
				rows.add(row.getValue("ns").stringValue() + "=" + longValue(row, "star") + "="
						+ longValue(row, "subjects") + "=" + longValue(row, "predicateRows") + "="
						+ longValue(row, "objects") + "=" + longValue(row, "predicates"));
			}
			assertThat(rows).containsExactly(EX + "a/=4=4=4=4=2", EX + "b#=2=2=2=2=1",
					EX + "end/=1=1=1=1=1");
			assertThat(LmdbNativePredicatePlaneGroups.PLANES.get() - planesBefore).isEqualTo(4L);
			assertThat(LmdbNativePredicatePlaneGroups.PREDICATE_DECODES.get() - decodesBefore).isEqualTo(4L);
		}
	}

	@Test
	public void restrictedDatasetUsesTheExactGenericPath() throws InterruptedException {
		LmdbStore store = openRepository();
		assertThat(store.awaitDirectAdjacencyReady(60, TimeUnit.SECONDS)).isTrue();
		String restricted = "SELECT ?ns (COUNT(*) AS ?statements) (COUNT(DISTINCT ?p) AS ?predicates) "
				+ "FROM <" + EX + "graph> WHERE { ?s ?p ?o . "
				+ "BIND(REPLACE(STR(?p), \"[^/#]+$\", \"\") AS ?ns) } GROUP BY ?ns";

		try (SailRepositoryConnection connection = repository.getConnection()) {
			List<BindingSet> rows = QueryResults.asList(connection.prepareTupleQuery(restricted).evaluate());
			assertThat(rows).hasSize(1);
			assertThat(rows.get(0).getValue("ns").stringValue()).isEqualTo(EX + "a/");
			assertThat(longValue(rows.get(0), "statements")).isEqualTo(1L);
			assertThat(longValue(rows.get(0), "predicates")).isEqualTo(1L);
			assertThat(executionPath(connection, restricted)).isNotEqualTo("predicatePlaneGroups");
		}
	}

	private LmdbStore openRepository() {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc"));
		repository = new SailRepository(store);
		try (SailRepositoryConnection connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			IRI p1 = vf.createIRI(EX + "a/p1");
			IRI p2 = vf.createIRI(EX + "a/p2");
			IRI p3 = vf.createIRI(EX + "b#p3");
			IRI trailingSeparator = vf.createIRI(EX + "end/");
			IRI graph = vf.createIRI(EX + "graph");
			connection.begin();
			connection.add(vf.createIRI(EX + "s1"), p1, vf.createIRI(EX + "o1"));
			connection.add(vf.createIRI(EX + "s1"), p1, vf.createIRI(EX + "o1"), graph);
			connection.add(vf.createIRI(EX + "s2"), p1, vf.createIRI(EX + "o2"));
			connection.add(vf.createIRI(EX + "s3"), p2, vf.createIRI(EX + "o3"));
			connection.add(vf.createIRI(EX + "s4"), p3, vf.createIRI(EX + "o4"));
			connection.add(vf.createIRI(EX + "s5"), p3, vf.createIRI(EX + "o5"));
			connection.add(vf.createIRI(EX + "s6"), trailingSeparator, vf.createIRI(EX + "o6"));
			connection.commit();
		}
		return store;
	}

	private static String executionPath(SailRepositoryConnection connection, String query) {
		return findExecutionPath(connection.prepareTupleQuery(query)
				.explain(Explanation.Level.Telemetry)
				.toGenericPlanNode());
	}

	private static long longValue(BindingSet row, String name) {
		return ((Literal) row.getValue(name)).longValue();
	}

	private static String findExecutionPath(GenericPlanNode node) {
		if (node == null) {
			return null;
		}
		String path = node.getStringMetricActual("nativeExecutionPath");
		if (path != null) {
			return path;
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				String childPath = findExecutionPath(child);
				if (childPath != null) {
					return childPath;
				}
			}
		}
		return null;
	}
}
